type Session={id:string;title:string;reference_date?:string;join_code:string;join_url:string;status:string;current_activity_id:string|null;expires_at:string;retention_days?:number;allow_anonymous?:boolean;show_results?:boolean;theme?:any};type Activity={id:string;type:'poll'|'quiz'|'timed_quiz'|'slide';title:string;options:{id:string;label:string}[];correct_option_id?:string;status:string;duration_seconds:number|null;opened_at?:string;answer_mode?:'single'|'multiple'|'text'|'file';answer_required?:boolean};type Snapshot={connected_participants?:number;session:Session;activities:Activity[];results:{activity_id:string;option_id:string;count:number}[];totals:{activity_id:string;count:number}[]};
async function request<T=any>(url:string,method='GET',body?:unknown):Promise<T>{const res=await fetch('/api'+url,{method,credentials:'include',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!res.ok){let info:any={};try{info=await res.json()}catch{}throw new Error(info.error||`HTTP ${res.status}`)}return res.json()}
function useLive(id:string|undefined,update:(s:Snapshot)=>void,onConnection?:(state:'connecting'|'connected'|'disconnected')=>void){
 useEffect(()=>{
  if(!id)return;
  let ws:WebSocket|undefined;
  let retry:number|undefined;
  let closed=false;
  let attempt=0;
  const open=()=>{
   if(closed||!navigator.onLine)return;
   onConnection?.('connecting');
   ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/live?session=${encodeURIComponent(id)}`);
   ws.onopen=()=>{attempt=0;onConnection?.('connected')};
   ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.type==='snapshot'&&m.data?.session?.id===id)update(m.data)}catch{}};
   ws.onclose=(event)=>{if(closed)return;onConnection?.('disconnected');if((event.code===4003||event.code===1008)||!navigator.onLine)return;retry=window.setTimeout(open,nextLiveRetryMs(attempt++))};
   ws.onerror=()=>ws?.close();
  };
  const onOnline=()=>{if(closed)return;if(retry!==undefined)window.clearTimeout(retry);if(!ws||ws.readyState===WebSocket.CLOSED)open()};
  const onOffline=()=>{onConnection?.('disconnected');if(retry!==undefined)window.clearTimeout(retry);ws?.close()};
  window.addEventListener('online',onOnline);window.addEventListener('offline',onOffline);
  open();
  return()=>{closed=true;if(retry!==undefined)window.clearTimeout(retry);window.removeEventListener('online',onOnline);window.removeEventListener('offline',onOffline);ws?.close()};
 },[id]);
}
