function PageTimer({openedAt,duration,label}:{openedAt?:string;duration?:number|null;label?:string}){const [now,setNow]=useState(Date.now());useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return ()=>clearInterval(id)},[]);if(!duration||!openedAt)return <p>⏱ {label||'Timer non impostato'}</p>;const left=Math.max(0,Math.ceil((new Date(openedAt).getTime()+duration*1000-now)/1000));return <p role="timer" aria-label="Secondi rimanenti">⏱ {label||'Tempo rimanente'}: {Math.floor(left/60)}:{String(left%60).padStart(2,'0')}</p>}
