 {widgets.filter((w:any)=>w.kind!=='results-button').map((w:any)=><div key={w.id} className="projection-widget" style={w.position?{position:'absolute',left:w.position.x+'%',top:w.position.y+'%',width:w.position.width+'%',height:(w.position.height||24)+'%',transform:`rotate(${w.position.rotation||0}deg)`}:undefined}><ProjectionWidgetContent sessionId={sessionId} widget={w} activity={activity}/></div>)}
