 return <section className="widget-question" aria-label={widget.label||'Domande sul tema'}><strong>{widget.label||'Domande sul tema'}</strong><textarea maxLength={2000} rows={3} value={body} placeholder="Scrivi una domanda su questo argomento" onChange={e=>setBody(e.target.value)}/><button type="button" disabled={body.trim().length<5} onClick={()=>void submit()}>Invia domanda</button><small aria-live="polite">{message}</small></section>
