 const deleteSelected=()=>{const ids=groupSelection();if(!ids.length)return;onChange(deleteWidgetSelection(widgets,ids));setSelectedWidgets([]);setActive(null);setContextWidget(null);setEditing(null)};
 const duplicateSelected=()=>{const ids=groupSelection();if(!ids.length)return;const selected=widgets.filter(w=>ids.includes(w.id));const result=duplicateWidgetSelection(widgets,ids,selected.map(w=>`${w.kind}-${crypto.randomUUID()}`));onChange(result.widgets);setSelectedWidgets(result.selected);setActive(result.selected[0]||null)};
